    "speech.needsFreeAbout": "\u041D\u0443\u0436\u043D\u043E \u2248{need} \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0433\u043E \u043C\u0435\u0441\u0442\u0430; \u043D\u0430 {drive} \u0435\u0441\u0442\u044C {free}",
